=== FILE: sync_fifo.v ===
// sync_fifo: parameterizable single-clock FIFO with first-word fall-through.
// Implements interface_spec.md / microarchitecture.md (task prj-89e77b6204:rtl-implementation).
`default_nettype none

module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    // ------------------------------------------------------------------
    // Widths and exact-width constants
    // ------------------------------------------------------------------
    localparam integer AW     = $clog2(DEPTH);
    localparam integer CW     = $clog2(DEPTH + 1);
    localparam integer LAST_I = DEPTH - 1;
    localparam integer ONE_I  = 1;

    localparam [AW-1:0] ZERO_A = {AW{1'b0}};
    localparam [AW-1:0] ONE_A  = ONE_I[AW-1:0];
    localparam [AW-1:0] LAST   = LAST_I[AW-1:0];
    localparam [CW-1:0] ZERO_C = {CW{1'b0}};
    localparam [CW-1:0] ONE_C  = ONE_I[CW-1:0];
    localparam [CW-1:0] FULL_C = DEPTH[CW-1:0];

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg [WIDTH-1:0] mem [0:DEPTH-1];   // datapath storage, not reset
    reg [AW-1:0]    wr_ptr;            // next slot to write
    reg [AW-1:0]    rd_ptr;            // oldest entry
    reg [CW-1:0]    count_q;           // entries held

    reg [AW-1:0]    wr_ptr_d;
    reg [AW-1:0]    rd_ptr_d;
    reg [CW-1:0]    count_d;

    wire            wr_acc;
    wire            rd_acc;

    // ------------------------------------------------------------------
    // Flags, acceptance, outputs
    // ------------------------------------------------------------------
    assign full    = (count_q == FULL_C);
    assign empty   = (count_q == ZERO_C);
    assign count   = count_q;

    assign wr_acc  = wr_en & ~full;
    assign rd_acc  = rd_en & ~empty;

    // First-word fall-through: combinational read of the oldest slot.
    assign rd_data = mem[rd_ptr];

    // ------------------------------------------------------------------
    // Next-state logic
    // ------------------------------------------------------------------
    always @* begin
        wr_ptr_d = wr_ptr;
        if (wr_acc) begin
            if (wr_ptr == LAST) begin
                wr_ptr_d = ZERO_A;
            end else begin
                wr_ptr_d = wr_ptr + ONE_A;
            end
        end
    end

    always @* begin
        rd_ptr_d = rd_ptr;
        if (rd_acc) begin
            if (rd_ptr == LAST) begin
                rd_ptr_d = ZERO_A;
            end else begin
                rd_ptr_d = rd_ptr + ONE_A;
            end
        end
    end

    always @* begin
        count_d = count_q;
        case ({wr_acc, rd_acc})
            2'b10:   count_d = count_q + ONE_C;
            2'b01:   count_d = count_q - ONE_C;
            default: count_d = count_q;
        endcase
    end

    // ------------------------------------------------------------------
    // Registers (synchronous, active-low reset)
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= ZERO_A;
            rd_ptr  <= ZERO_A;
            count_q <= ZERO_C;
        end else begin
            wr_ptr  <= wr_ptr_d;
            rd_ptr  <= rd_ptr_d;
            count_q <= count_d;
        end
    end

    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr] <= wr_data;
        end
    end

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Formal properties
    // ------------------------------------------------------------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active on the first cycle.
    always @* begin
        if (!f_past_valid) assume(!rst_n);
    end

    // Expected write pointer: (rd_ptr + count) mod DEPTH.
    wire [31:0] f_sum    = rd_ptr + count_q;
    wire [31:0] f_wr_exp = (f_sum >= DEPTH) ? (f_sum - DEPTH) : f_sum;

    // Structural invariants.
    always @* begin
        if (f_past_valid) begin
            assert(count_q <= FULL_C);
            assert(rd_ptr <= LAST);
            assert(wr_ptr <= LAST);
            assert(wr_ptr == f_wr_exp[AW-1:0]);
            assert(full  == (count_q == FULL_C));
            assert(empty == (count_q == ZERO_C));
            assert(!(full && empty));
        end
    end

    // One solver-chosen slot, tracked against a shadow of its last write.
    (* anyconst *) reg [AW-1:0] f_addr;
    always @* assume(f_addr <= LAST);

    reg [WIDTH-1:0] f_shadow;
    always @(posedge clk) begin
        if (rst_n && wr_acc && (wr_ptr == f_addr)) f_shadow <= wr_data;
    end

    wire [WIDTH-1:0] f_word = mem[f_addr];
    wire [31:0]      f_dist = (f_addr >= rd_ptr) ? (f_addr - rd_ptr)
                                                 : (DEPTH + f_addr - rd_ptr);
    wire             f_live = (f_dist < count_q);

    always @* begin
        if (f_past_valid) begin
            if (f_live) assert(f_word == f_shadow);
            if (!empty && (rd_ptr == f_addr)) assert(rd_data == f_shadow);
        end
    end

    reg [WIDTH-1:0] f_word_q;
    always @(posedge clk) f_word_q <= f_word;

    // Step properties.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert(count_q == ZERO_C);
                assert(wr_ptr == ZERO_A);
                assert(rd_ptr == ZERO_A);
                assert(empty);
                assert(!full);
            end else begin
                case ({$past(wr_acc), $past(rd_acc)})
                    2'b10:   assert(count_q == $past(count_q) + ONE_C);
                    2'b01:   assert(count_q == $past(count_q) - ONE_C);
                    default: assert(count_q == $past(count_q));
                endcase
                if (!$past(wr_acc)) assert(wr_ptr == $past(wr_ptr));
                if (!$past(rd_acc)) assert(rd_ptr == $past(rd_ptr));
                if ($past(wr_en) && $past(full)) begin
                    assert(!$past(wr_acc));
                    assert(wr_ptr == $past(wr_ptr));
                    assert(f_word == f_word_q);
                end
                if ($past(rd_en) && $past(empty)) begin
                    assert(!$past(rd_acc));
                    assert(rd_ptr == $past(rd_ptr));
                    if (!$past(wr_en)) begin
                        assert(empty);
                        assert(count_q == ZERO_C);
                    end
                end
            end
        end
    end

    // Covers: the promised behaviour is reachable.
    reg f_was_full;
    always @(posedge clk) begin
        if (!rst_n)    f_was_full <= 1'b0;
        else if (full) f_was_full <= 1'b1;
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n && $past(rst_n)) begin
            cover(full);
            cover(f_was_full && empty);
            cover($past(full)  && $past(wr_en) && $past(rd_en));
            cover($past(empty) && $past(wr_en) && $past(rd_en));
            cover($past(wr_acc) && $past(rd_acc));
            cover($past(wr_acc) && ($past(wr_ptr) == LAST));
            cover($past(rd_acc) && ($past(rd_ptr) == LAST));
            cover($past(rd_acc) && ($past(rd_ptr) == f_addr));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
