// sync_fifo_tb: self-checking testbench for sync_fifo.
// Two FIFOs on the same stimulus: DEPTH 8 x WIDTH 8 and DEPTH 5 x WIDTH 12,
// each checked every cycle against a reference queue.
module sync_fifo_tb;

    reg         clk;
    reg         rst_n;
    reg         wr_en;
    reg         rd_en;
    reg  [11:0] wr_data;

    wire        full8;
    wire        empty8;
    wire [7:0]  rd_data8;
    wire [3:0]  count8;

    wire        full5;
    wire        empty5;
    wire [11:0] rd_data5;
    wire [2:0]  count5;

    sync_fifo #(.DEPTH(8), .WIDTH(8)) u_fifo8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data[7:0]),
        .full    (full8),
        .rd_en   (rd_en),
        .rd_data (rd_data8),
        .empty   (empty8),
        .count   (count8)
    );

    sync_fifo #(.DEPTH(5), .WIDTH(12)) u_fifo5 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .full    (full5),
        .rd_en   (rd_en),
        .rd_data (rd_data5),
        .empty   (empty5),
        .count   (count5)
    );

    // Reference models
    reg [7:0]  q8 [0:7];
    reg [11:0] q5 [0:4];
    integer    c8, h8, c5, h5, t;
    reg [2:0]  idx;
    reg        acc_w, acc_r;
    reg        seen_full8, seen_full5;

    // Bookkeeping
    integer passed, failed, cyc, rc, i;
    integer cv_full8, cv_wfull8, cv_drain8, cv_rempty8, cv_wre8, cv_wrf8, cv_wrm8;
    integer cv_wwrap8, cv_rwrap8, cv_rst8;
    integer cv_full5, cv_wfull5, cv_drain5, cv_rempty5, cv_wre5, cv_wrf5, cv_wrm5;
    integer cv_wwrap5, cv_rwrap5, cv_rst5;
    reg [8*64-1:0] nonce;
    reg [31:0]     rnd;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task check;
        input            ok;
        input [8*24-1:0] what;
        begin
            if (ok) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("cycle %0d: check failed: %0s", cyc, what);
            end
        end
    endtask

    task model8;
        begin
            acc_w = wr_en && (c8 != 8);
            acc_r = rd_en && (c8 != 0);
            if (!rst_n) begin
                if (c8 != 0) cv_rst8 = cv_rst8 + 1;
                c8 = 0;
                h8 = 0;
                seen_full8 = 1'b0;
            end else begin
                if (wr_en && (c8 == 8)) cv_wfull8  = cv_wfull8 + 1;
                if (rd_en && (c8 == 0)) cv_rempty8 = cv_rempty8 + 1;
                if (wr_en && rd_en) begin
                    if (c8 == 0)      cv_wre8 = cv_wre8 + 1;
                    else if (c8 == 8) cv_wrf8 = cv_wrf8 + 1;
                    else              cv_wrm8 = cv_wrm8 + 1;
                end
                if (acc_w) begin
                    t = (h8 + c8) % 8;
                    if (t == 7) cv_wwrap8 = cv_wwrap8 + 1;
                    idx = t[2:0];
                    q8[idx] = wr_data[7:0];
                end
                if (acc_r) begin
                    if (h8 == 7) cv_rwrap8 = cv_rwrap8 + 1;
                    h8 = (h8 + 1) % 8;
                end
                c8 = c8 + (acc_w ? 1 : 0) - (acc_r ? 1 : 0);
                if (c8 == 8) begin
                    cv_full8   = cv_full8 + 1;
                    seen_full8 = 1'b1;
                end
                if ((c8 == 0) && acc_r && seen_full8) begin
                    cv_drain8  = cv_drain8 + 1;
                    seen_full8 = 1'b0;
                end
            end
        end
    endtask

    task model5;
        begin
            acc_w = wr_en && (c5 != 5);
            acc_r = rd_en && (c5 != 0);
            if (!rst_n) begin
                if (c5 != 0) cv_rst5 = cv_rst5 + 1;
                c5 = 0;
                h5 = 0;
                seen_full5 = 1'b0;
            end else begin
                if (wr_en && (c5 == 5)) cv_wfull5  = cv_wfull5 + 1;
                if (rd_en && (c5 == 0)) cv_rempty5 = cv_rempty5 + 1;
                if (wr_en && rd_en) begin
                    if (c5 == 0)      cv_wre5 = cv_wre5 + 1;
                    else if (c5 == 5) cv_wrf5 = cv_wrf5 + 1;
                    else              cv_wrm5 = cv_wrm5 + 1;
                end
                if (acc_w) begin
                    t = (h5 + c5) % 5;
                    if (t == 4) cv_wwrap5 = cv_wwrap5 + 1;
                    idx = t[2:0];
                    q5[idx] = wr_data;
                end
                if (acc_r) begin
                    if (h5 == 4) cv_rwrap5 = cv_rwrap5 + 1;
                    h5 = (h5 + 1) % 5;
                end
                c5 = c5 + (acc_w ? 1 : 0) - (acc_r ? 1 : 0);
                if (c5 == 5) begin
                    cv_full5   = cv_full5 + 1;
                    seen_full5 = 1'b1;
                end
                if ((c5 == 0) && acc_r && seen_full5) begin
                    cv_drain5  = cv_drain5 + 1;
                    seen_full5 = 1'b0;
                end
            end
        end
    endtask

    task check8;
        begin
            check(count8 == c8[3:0],  "fifo8 count");
            check(full8  == (c8 == 8), "fifo8 full");
            check(empty8 == (c8 == 0), "fifo8 empty");
            if (c8 != 0) begin
                idx = h8[2:0];
                check(rd_data8 == q8[idx], "fifo8 rd_data");
            end
        end
    endtask

    task check5;
        begin
            check(count5 == c5[2:0],  "fifo5 count");
            check(full5  == (c5 == 5), "fifo5 full");
            check(empty5 == (c5 == 0), "fifo5 empty");
            if (c5 != 0) begin
                idx = h5[2:0];
                check(rd_data5 == q5[idx], "fifo5 rd_data");
            end
        end
    endtask

    // Drive inputs (at a falling edge), let one rising edge act,
    // update the models, then check at the next falling edge.
    task cycle;
        input        w;
        input        r;
        input [11:0] d;
        begin
            wr_en   = w;
            rd_en   = r;
            wr_data = d;
            @(posedge clk);
            model8;
            model5;
            @(negedge clk);
            cyc = cyc + 1;
            check8;
            check5;
        end
    endtask

    task run_random;
        input integer cycles;
        input [7:0]   wp;
        input [7:0]   rp;
        integer k;
        begin
            for (k = 0; k < cycles; k = k + 1) begin
                rnd = $random;
                cycle(rnd[7:0] < wp, rnd[15:8] < rp, rnd[27:16]);
            end
        end
    endtask

    initial begin
        nonce  = {(8*64){1'b0}};
        passed = 0;
        failed = 0;
        cyc    = 0;
        c8 = 0; h8 = 0; c5 = 0; h5 = 0; t = 0;
        idx = 3'd0;
        acc_w = 1'b0; acc_r = 1'b0;
        seen_full8 = 1'b0; seen_full5 = 1'b0;
        cv_full8 = 0; cv_wfull8 = 0; cv_drain8 = 0; cv_rempty8 = 0; cv_wre8 = 0;
        cv_wrf8 = 0; cv_wrm8 = 0; cv_wwrap8 = 0; cv_rwrap8 = 0; cv_rst8 = 0;
        cv_full5 = 0; cv_wfull5 = 0; cv_drain5 = 0; cv_rempty5 = 0; cv_wre5 = 0;
        cv_wrf5 = 0; cv_wrm5 = 0; cv_wwrap5 = 0; cv_rwrap5 = 0; cv_rst5 = 0;
        rnd = 32'd0;
        rc  = $value$plusargs("nirmaan_nonce=%s", nonce);

        rst_n   = 1'b0;
        wr_en   = 1'b0;
        rd_en   = 1'b0;
        wr_data = 12'h000;

        // First rising edge applies reset; check the empty state.
        @(negedge clk);
        check8;
        check5;

        // Requests during reset are ignored.
        cycle(1'b1, 1'b1, 12'h0AA);
        cycle(1'b1, 1'b0, 12'h0BB);
        rst_n = 1'b1;

        // Read while empty.
        cycle(1'b0, 1'b1, 12'h000);
        cycle(1'b0, 1'b1, 12'h000);

        // Write and read together when empty: only the write is accepted.
        cycle(1'b1, 1'b1, 12'h123);
        cycle(1'b0, 1'b1, 12'h000);

        // Fill to full, with writes while full.
        for (i = 0; i < 10; i = i + 1) begin
            cycle(1'b1, 1'b0, {4'h5, i[7:0]});
        end

        // Write and read together when full: only the read is accepted.
        cycle(1'b1, 1'b1, 12'hF0F);

        // Write and read together in between.
        cycle(1'b1, 1'b1, 12'h3C1);
        cycle(1'b1, 1'b1, 12'h3C2);
        cycle(1'b1, 1'b1, 12'h3C3);

        // Back to full, then a write while full.
        cycle(1'b1, 1'b0, 12'h7A1);
        cycle(1'b1, 1'b0, 12'h7A2);
        cycle(1'b1, 1'b0, 12'h7A3);

        // Drain to empty, then read while empty.
        for (i = 0; i < 12; i = i + 1) begin
            cycle(1'b0, 1'b1, 12'h000);
        end

        // Partial fill, then steady write+read (pointer wrap-around).
        cycle(1'b1, 1'b0, 12'h901);
        cycle(1'b1, 1'b0, 12'h902);
        cycle(1'b1, 1'b0, 12'h903);
        for (i = 0; i < 12; i = i + 1) begin
            cycle(1'b1, 1'b1, {4'hA, i[7:0]});
        end

        // Reset during traffic.
        rst_n = 1'b0;
        cycle(1'b1, 1'b1, 12'hDEA);
        cycle(1'b1, 1'b0, 12'hDEB);
        rst_n = 1'b1;

        // Random traffic with random stalls on both sides.
        run_random(250, 8'd200, 8'd60);
        rst_n = 1'b0;
        cycle(1'b1, 1'b1, 12'hBAD);
        cycle(1'b0, 1'b1, 12'hBAE);
        rst_n = 1'b1;
        run_random(250, 8'd60,  8'd200);
        run_random(250, 8'd128, 8'd128);
        run_random(250, 8'd240, 8'd240);
        run_random(250, 8'd30,  8'd30);
        run_random(250, 8'd220, 8'd128);
        run_random(250, 8'd128, 8'd220);
        run_random(250, 8'd255, 8'd255);

        // Coverage: every corner case must have been reached.
        check(cv_full8   > 0, "cover fifo8 full");
        check(cv_wfull8  > 0, "cover fifo8 wr full");
        check(cv_drain8  > 0, "cover fifo8 drain");
        check(cv_rempty8 > 0, "cover fifo8 rd empty");
        check(cv_wre8    > 0, "cover fifo8 wr+rd empty");
