        check(cv_wwrap8  > 0, "cover fifo8 wr wrap");
        check(cv_rwrap8  > 0, "cover fifo8 rd wrap");
        check(cv_rst8    > 0, "cover fifo8 rst traffic");
        check(cv_full5   > 0, "cover fifo5 full");
        check(cv_wfull5  > 0, "cover fifo5 wr full");
        check(cv_drain5  > 0, "cover fifo5 drain");
        check(cv_rempty5 > 0, "cover fifo5 rd empty");
